values
  ($t$0406$t$, $t$Berlin Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Berlin Township requires a resale certificate. Call the office before closing.","Contact: Michael DePalma, Construction Official · 856-767-1854"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://berlintwp.com/planning-zoning-board/$t$, $j$[{"url":"https://berlintwp.com/planning-zoning-board/","label":"Official source (berlintwp.com)"},{"url":"https://berlintwp.com/contact/","label":"Official source (berlintwp.com)"}]$j$::jsonb, $t$Michael DePalma Construction Official$t$, $t$2e1e262ecaf97ffd9455870a5cd24b280332b92c496dbe8973f56c7fcbafc216$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":8,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0406.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0406.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0406$t$, $t$Berlin Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Berlin Township Fire District No. 1, Bureau of Fire Prevention (fire district)","Contact: Joseph V Cornforth, Fire Official · 856-767-1839 · firemarshal222@gmail.com","Apply: More than 10 business days before the change of occupant for the lowest fee; form and check must be in before an appointment is made","How to apply: Fill out the district's Application for Certification of Smoke Detector and Carbon Monoxide Alarm Compliance and send it with a check to the Bureau of Fire Prevention, Berlin Township Fire District #1, 186 Haddon Avenue, West Berlin, NJ 08091 (fax 856-767-2248). The completed form and check must be received before an appointment is scheduled. Fees are non-refundable. The only form found is a 2017 version once posted on the Township website (Internet Archive copy); confirm the current form and fees with the district.","Fire official in the NJ state directory (fire district), updated 8/5/2026: Joseph V Cornforth · (856) 767-1839 · firemarshal222@gmail.com","District web page (2016) says the resale inspection checks smoke detectors, carbon monoxide alarms and a fire extinguisher; state law dropped the extinguisher in 2025, so confirm the current rule with the district","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request more than 10 business days before scheduling/change of occupant (2017 district form)","amount":"$45.00"},{"label":"Request 4 to 10 business days before (2017 district form)","amount":"$90.00"},{"label":"Request fewer than 4 business days before (2017 district form)","amount":"$161.00"},{"label":"Re-inspection (2017 district form)","amount":"$20.00"}]$j$::jsonb, $t$https://web.archive.org/web/20190921045451/https://berlintwp.com/wp-content/uploads/2018/05/Smoke-Detector-Carbon-Monoxide-Detector-Application.pdf$t$, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/divisions/dlgs/programs/lpcl_docs/cd_camden.docx","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20190921045451/https://berlintwp.com/wp-content/uploads/2018/05/Smoke-Detector-Carbon-Monoxide-Detector-Application.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20160318035219/http://westberlinfire.com/fire-prevention/","label":"Official source (web.archive.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$D Berlin Township$t$, $t$ea66610b985bd482a0a09fffaddcc8b41ed0070848056e273a284a94611c3074$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":8,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0406.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0406.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0902$t$, $t$East Newark Borough$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for resale (Certificate of Continued Occupancy)$t$, $j$["Issued by: East Newark Building & Construction Department (Construction Code Enforcement Department)","Contact: Bruno Silva, Construction Official / Building Subcode Official (part time) · 973-481-2902, ext. 232 · constructionta@boroughofeastnewark.com","Apply: Borough recommends having the inspection done as soon as the sales contract is signed","How to apply: Fill out the Borough's Application for Zoning Certificate (the residential Certificate of Occupancy form) with block and lot, seller and buyer names, number of units and the approximate closing date, and pay by check or cash at the Building Department, Municipal Building, 34 Sherman Avenue. The Building Department checks for open permits, zoning, penalties and state housing violations, and the Fire Department signs off on smoke detectors. Use the Borough's Certificate of Continued Occupancy checklist to prepare for the inspection.","Ten-year sealed smoke alarms within 10 feet outside each bedroom door, plus the usual basement and first floor locations near the stairs","Carbon monoxide alarm (battery or plug-in) outside sleeping areas","Portable fire extinguisher (2A:10B:C, no more than 10 lbs) mounted within 10 feet of each kitchen in the exit path (2021 checklist; state law dropped this in 2025)","Covers on all switches, outlets and junction boxes","Handrail on any stairs with more than three risers; guard railings where the drop is 30 inches or more","Pressure relief discharge pipe on boilers and water heaters, ending 6 to 8 inches above the floor","Working faucets and toilets","Attached garage fire separation kept intact, with a fire-rated self-closing door into the house","No double cylinder deadbolts on exit doors","Gas piping strapped, shut-off valves near appliances, unused lines capped, no aluminum gas piping","No broken or missing glass","Sheds at least 3 feet from property lines","Sidewalks, stairs, driveways, fences and garages in good repair; yard free of debris and overgrowth","House numbers at least 4 inches tall and visible from the street","Sound roof, leaders that drain away from the foundation, painted exterior walls, and repaired interior plaster, paint and floors","Also: Open permits, zoning and penalties checked: The CO application's office section records use group, open permits, zone, monetary penalties, legal use, Fire Department smoke detector sign-off, and State Housing violations and registration number."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy on sale or transfer of owner or renter, residential, per unit (Ord. 10-2025 raised it from $50)","amount":"$75.00"},{"label":"Certificate of Continued Occupancy (separate line in the same fee table; the ordinance does not say when it applies instead of the per-unit sale fee)","amount":"$250"},{"label":"Temporary Certificate of Occupancy","amount":"$50.00"}]$j$::jsonb, $t$https://www.boroughofeastnewark.com/_Content/pdf/forms/CO-Application.pdf$t$, $t$https://www.boroughofeastnewark.com/Departments/building-and-construction$t$, $j$[{"url":"https://www.boroughofeastnewark.com/_Content/pdf/forms/Smoke-CO-Fire-Ext.pdf","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/_Content/pdf/forms/CCO-Instructions.pdf","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/_Content/pdf/forms/CO-Application.pdf","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/_Content/pdf/minutes/2025-05-14-Council-Minutes.pdf","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/api/data/GetDirectoryDepartmentsData","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/_Content/pdf/minutes/2024-09-11-Council-Minutes.pdf","label":"Official source (boroughofeastnewark.com)"}]$j$::jsonb, $t$The Uniform Fire Code is now requiring that fire extinguishers be installed, along with smoke and carbon monoxide detectors, as an essential part of the inspection for a Certificate of Occupancy, required for resales.$t$, $t$82b90ff7a294cfdc5c6dc642f18dad837adec40f6d6b87b3beca4ab4bfec5dc9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0902.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0902.json$t$, true),
  ($t$0902$t$, $t$East Newark Borough$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: East Newark Fire Prevention Bureau (town fire bureau)","Contact: Juan C. Barroso Jr., Fire Code Official · 973-481-2902, ext. 234 · fireprevention@boroughofeastnewark.com","How to apply: The smoke and carbon monoxide check is done as part of the resale Certificate of Occupancy process; the Borough's CO application has a Fire Department (smoke detectors) sign-off line. The Borough also posts an Application for One and Two Families, Certification of Smoke Detector and Carbon Monoxide Detector Compliance, from the Construction Code Department. Call the Fire Prevention Bureau to confirm how to schedule and pay.","Fire official in the NJ state directory, updated 7/13/2026: Juan C Barroso Jr · (973) 481-2902 · fireprevention@boroughofeastnewar","Ten-year sealed battery smoke alarms (required since January 22, 2019) on each level and outside each sleeping area within 10 feet of bedrooms, on or near the ceiling","Carbon monoxide alarm (battery, hard-wired or plug-in) outside each sleeping area within 10 feet of bedrooms, UL 2034 listed","Borough handout (2020) still lists a 2A:10B:C portable fire extinguisher, no more than 10 pounds, mounted within 10 feet of each kitchen in the exit path; a kitchen-only extinguisher does not pass","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.boroughofeastnewark.com/_Content/pdf/forms/Smoke-Carbon-Monoxide-Certification.pdf$t$, $t$https://www.boroughofeastnewark.com/Departments/fire-prevention-bureau$t$, $j$[{"url":"https://www.boroughofeastnewark.com/Departments/fire-prevention-bureau","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/api/data/GetDirectoryDepartmentsData","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/_Content/pdf/minutes/2026-01-07-Council-Minutes.pdf","label":"Official source (boroughofeastnewark.com)"},{"url":"https://www.boroughofeastnewark.com/_Content/pdf/forms/Smoke-CO-Fire-Ext.pdf","label":"Official source (boroughofeastnewark.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Code Official Juan C. Barroso Jr.$t$, $t$7139be382e09fb82a7615ea8c8b1fec51a1351294c8e658a0752940d202cfc2f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0902.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0902.json$t$, true),
  ($t$0903$t$, $t$Guttenberg$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Owner Certificate (Certificate of Occupancy before sale, also called Certificate of Continued Occupancy)$t$, $j$["Issued by: Guttenberg Building Department (Construction Official)","Contact: Yomaris Alcantara, Technical Assistant to the Construction Official · 201-868-2315, ext. 106 or 149 · Yalcantara@myguttenberg.com","Apply: Standard inspection has no stated lead time; an expedited inspection (done within 3 business days) costs an extra $50","How to apply: The purchaser completes the Residential Owner Certificate application (page 1) and the Certification/Affidavit (page 2), both signed with original signatures and notarized, and files it with the Building Department, Town Hall, 6808 Park Avenue, Guttenberg, with a check or money order payable to Town of Guttenberg. The Building Department then inspects.","Purchaser fills out and signs the application with original signatures, notarized, plus a notarized affidavit stating the number of dwelling units and that they buy the property as is and are responsible for outstanding violations","LLC buyers or sellers must give the actual name of the manager or principal","Boilers and furnaces need a full fire rated ceiling or a sprinkler on the water line","All permits closed with final inspections done; no open building code or property maintenance violations","Exits clear; no padlocks or key locks on exit doors; no keyed locks on interior doors","Handrails on stairs with three or more risers","Working smoke and carbon monoxide detectors","Fire extinguisher within 10 feet of the kitchen, properly mounted and easy to reach","Windows open and have no broken or cracked glass","No trash or rubbish buildup inside or outside","Inspector must have access to all areas of the property","Also: Open permits must be closed: The resale inspection checklist requires final inspections on any permits and no outstanding building code or property maintenance violations."]$j$::jsonb, $j$[{"label":"Continued certificate of occupancy inspection, townhouse, condominium or one-family (Ord. 06-24, 2024)","amount":"$100"},{"label":"Continued certificate of occupancy inspection, two-family house (Ord. 06-24, 2024)","amount":"$125"},{"label":"Expedited inspection, completed within three business days, added to the fee above","amount":"$50"},{"label":"Re-inspection after a failed inspection, each time","amount":"$40"},{"label":"Continued certificate of occupancy, any use group (separate line in the 2024 ordinance; unclear whether it is charged in addition to the inspection fee)","amount":"$100"},{"label":"Cancelling or rescheduling an inspection less than 24 hours ahead (Ord. 22-23, 2023)","amount":"$40"}]$j$::jsonb, $t$https://www.guttenbergnj.org/_Content/pdf/forms/Residential-Owner-Certificate.pdf$t$, $t$https://www.guttenbergnj.org/Departments/building-department$t$, $j$[{"url":"https://www.guttenbergnj.org/_Content/pdf/minutes/2023-08-28-Council-Minutes.pdf","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/_Content/pdf/minutes/2024-05-22-Council-Minutes.pdf","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/_Content/pdf/forms/Residential-Owner-Certificate.pdf","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/api/data/GetDirectoryDepartmentsData","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/_Content/pdf/minutes/2025-05-28-Council-Minutes.pdf","label":"Official source (guttenbergnj.org)"}]$j$::jsonb, $t$Residential Owner Certificate. Any person who uses or intends to use, sell, convey, deliver or transfer, and for any purchaser to purchase, or take title or possession of, any residential building or premises shall apply for a residential certificate$t$, $t$af5bf2df07ad178ff6c68e5854f96b98acd999ec6a6425d16c0e87d7739c2eda$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":6,"fee_bad":0,"fee_unchecked":4,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0903.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0903.json$t$, true),
  ($t$0903$t$, $t$Guttenberg$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Guttenberg Fire Prevention (town fire bureau)","Contact: Albert Salvesen, Fire Official · 201-868-8564 ext. 105 · fireofficial@myguttenberg.com","Apply: Apply more than 10 business days before the change of occupancy for the lowest fee; certificates are valid for six months","How to apply: Fill out the Application for One, Two-Family Dwellings, Condominium, Co-op and Town House (Certification of Smoke Detector / Carbon Monoxide Alarm / Fire Extinguisher Compliance), check every box, and bring it to Guttenberg Fire Prevention, 6808 Park Avenue, with a check or money order payable to Town of Guttenberg. Credit cards are accepted with a surcharge. The application fee is not refunded.","Fire official in the NJ state directory (town), updated 1/12/2026: Albert Salvesen · (201) 868-8564 · fireofficial@myguttenberg.com","All smoke detectors must be 10-year sealed units (since January 1, 2019)","Smoke detector on each level including the basement (not the attic or crawl space); smoke detector and carbon monoxide alarm outside each sleeping area within 10 feet of bedrooms","Carbon monoxide alarms placed next to fuel burning equipment, and replaced if older than 8 to 10 years","All front doors leading to hallways must self-close","The July 2024 Town form still lists fire extinguishers mounted in the proper location (state law dropped the extinguisher in 2025)","Applications brought in after 12 noon count as the next business day","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/carbon monoxide certificate, more than 10 business days before change of occupancy","amount":"$45.00"},{"label":"4 to 10 business days before change of occupancy","amount":"$90.00"},{"label":"Fewer than 4 business days before change of occupancy","amount":"$161.00"},{"label":"Re-inspection","amount":"$40.00"}]$j$::jsonb, $t$https://www.guttenbergnj.org/_Content/pdf/forms/New-Certificate-of-Smoke-Detector-Carbon-Monoxide-Alarm.pdf$t$, $t$https://www.guttenbergnj.org/Departments/fire-prevention$t$, $j$[{"url":"https://www.guttenbergnj.org/_Content/pdf/forms/New-Certificate-of-Smoke-Detector-Carbon-Monoxide-Alarm.pdf","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/_Content/pdf/forms/Guidelines-for-Cert-of-Smoke-and-Carbon-Monoxide-Alarm.pdf","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/Departments/fire-prevention","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/api/data/GetDirectoryDepartmentsData","label":"Official source (guttenbergnj.org)"},{"url":"https://www.guttenbergnj.org/_Content/pdf/minutes/2026-01-05-Council-ReOrg-Minutes.pdf","label":"Official source (guttenbergnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$ALBERT SALVESEN FIRE OFFICIAL P 201-868-8564 Voice Mail Ext 105/123$t$, $t$0dd91c411d3dde048fe65865b4cfa8d3013bbd7ddc829ba1245b7194a124993c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":6,"fee_bad":0,"fee_unchecked":4,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0903.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0903.json$t$, true),
  ($t$0904$t$, $t$Harrison$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (Transfer of Title Certificate of Occupancy)$t$, $j$["Issued by: Department of Construction and Zoning (Construction & Engineering); the Zoning Office does the inspection","Contact: Stephen Woods, Building Subcode Official and Zoning Officer · 973-268-2446 · swoods@townofharrison.com","How to apply: Fill out the Transfer of Title Application (block and lot, owner and purchaser, number of dwelling units, approximate closing date, use) and pay by check or cash at the Department of Construction and Zoning. The Zoning Office inspects and the Zoning Official or designee signs off. Office hours are Monday to Friday, 8 a.m. to 4:30 p.m. Inspections can also be requested by email to inspections@townofharrison.com.","General inspection of the visible parts of the building; no violations or unsafe conditions","Existing use must be lawful and allowed by zoning","Open permits, monetary penalties, State Housing violations and registration are checked","Fire Department smoke detector sign-off","Lead-safe certification compliance under N.J.A.C. 5:28A","Application must name the new occupant(s); residential applications list every occupant with birth dates","Multiple dwellings attach their state certificate of registration","Also: Open permits and penalties: The Transfer of Title Application's office section checks open permits, monetary penalties and State Housing violations and registration before the certificate is signed.","Also: Lead-safe certification: The Transfer of Title Application includes a line for Lead Certification Compliance per N.J.A.C. 5:28A."]$j$::jsonb, $j$[{"label":"Transfer of Title or Change in Tenancy Certificate of Occupancy, residential use groups R-2, R-3 and R-4, per unit","amount":"$75.00"},{"label":"Continued Certificate of Occupancy, residential use groups R-2, R-3 and R-4, per unit (separate line in the same fee schedule)","amount":"$75.00"},{"label":"Temporary certificate tied to a change in title or tenancy, 1 and 2 family (first issuance or renewal)","amount":"$75.00"},{"label":"Certificate of continued occupancy application fee, per residential dwelling unit (Chapter 15.08, 1994; may overlap with the $75.00 fee above)","amount":"$15.00"}]$j$::jsonb, $t$https://www.townofharrison.com/DocumentCenter/View/2118/Transfer-of-Title-Application$t$, $t$https://townofharrison.com/313/Construction-Permits-and-Schedule-Inspec$t$, $j$[{"url":"https://townofharrison.com/313/Construction-Permits-and-Schedule-Inspec","label":"Official source (townofharrison.com)"},{"url":"https://api.municode.com/CodesContent?jobId=481661&nodeId=TIT15BUCO_CH15.08CECOOC_15.08.030CECOOCREWH&productId=16390","label":"Official source (api.municode.com)"},{"url":"https://api.municode.com/CodesContent?jobId=481661&nodeId=TIT15BUCO_CH15.04STUNCOCOEN_15.04.040COFESC&productId=16390","label":"Official source (api.municode.com)"},{"url":"https://www.townofharrison.com/DocumentCenter/View/2118/Transfer-of-Title-Application","label":"Official source (townofharrison.com)"},{"url":"https://api.municode.com/CodesContent?jobId=481661&nodeId=TIT15BUCO_CH15.08CECOOC_15.08.060APFE&productId=16390","label":"Official source (api.municode.com)"}]$j$::jsonb, $t$Perform inspections for the issuance of Certificates of Continued Occupancy in connection with the transfer of title or changes in occupancy.$t$, $t$cfc9fb294fddfa808549648bde13c268ec7c26b790c167f140274384ec0d7552$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0904.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0904.json$t$, true),
  ($t$0904$t$, $t$Harrison$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Harrison Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: George Kondek, Fire Official · 973-483-3039 · gkondek@townofharrison.com","How to apply: Contact the Fire Prevention Bureau at 634 Sussex Street. The Town's Transfer of Title Application includes a Fire Department smoke detector sign-off line, so the smoke/CO check is tied to the resale CO. No smoke/CO certificate form or fee was found online.","Fire official in the NJ state directory, updated 7/22/2026: George P Kondek · (973) 483-3039 · gkondek@townofharrison.com","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://townofharrison.com/151/Fire-Department$t$, $j$[{"url":"https://townofharrison.com/151/Fire-Department","label":"Official source (townofharrison.com)"},{"url":"https://api.municode.com/CodesContent?jobId=481661&nodeId=TIT8HESA_CH8.08UNFISAACEN&productId=16390","label":"Official source (api.municode.com)"},{"url":"https://www.townofharrison.com/DocumentCenter/View/2118/Transfer-of-Title-Application","label":"Official source (townofharrison.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Prevention Bureau Phone: 973-483-3039$t$, $t$52ea3c8cec17a9bea229acf27d9774099dddcb12e93cf16732514557005106ac$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0904.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0904.json$t$, true),
  ($t$0906$t$, $t$Jersey City$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Jersey City. Confirm with the office if the buyer's lender or title company asks.","Contact: Joseph Severini, Construction Code Official · (201) 547-5055 · ConstructionCode@jcnj.org","Also: Seller must disclose open code violations in the sale contract: City Code section 257-2: a seller must include a copy of any outstanding property maintenance violation notice or order in the agreement of sale.","Also: Lead paint notice to buyer: City Code section 257-4: before a binder, contract or deposit for the sale of a dwelling, the seller or broker must give the buyer the City's lead-based paint notice and keep the buyer's signed acknowledgment.","Also: Optional No Certificate of Occupancy letter: The Construction Official can issue a letter on whether a CO is required; the City fee schedule lists $50.00 for a No Certificate of Occupancy letter for real estate transfers."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.jerseycitynj.gov/cityhall/HousingAndDevelopment/constructioncode/inspections___certificates$t$, $j$[{"url":"https://www.jerseycitynj.gov/cityhall/HousingAndDevelopment/constructioncode/inspections___certificates","label":"Official source (jerseycitynj.gov)"},{"url":"https://www.jerseycitynj.gov/cityhall/HousingAndDevelopment/constructioncode","label":"Official source (jerseycitynj.gov)"},{"url":"https://api.municode.com/CodesContent?jobId=472619&nodeId=CH160FECH&productId=16093","label":"Official source (api.municode.com)"}]$j$::jsonb, $t$Please note: Jersey City does not issue New Certificates of Occupancy for the buying and selling of property.$t$, $t$d22449dd29d682f4cba7bf700187034a40e9d1069b2e755e837bc84cdca37bcd$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0906.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0906.json$t$, true),
  ($t$0906$t$, $t$Jersey City$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Jersey City Division of Fire, Fire Prevention Bureau (town fire bureau)","Contact: Omar Manning, Fire Official · (201) 547-4255 · FirePrevention@njjcps.org","How to apply: Fill out the Sale of Property Smoke Alarm, Carbon Monoxide Alarm Certification Form (property, owner, and an email for scheduling), bring it to Fire Headquarters, 2 Jackson Square Plaza / 356 Martin Luther King Drive, with a check or money order for $75.00 payable to City of Jersey City, then wait for an email from the fire inspector to set up the walk-through inspection.","Fire official in the NJ state directory, updated 2/6/2026: Omar Manning · (201) 547-4255 · omanning@njjcps.org","Ten-year sealed battery single station smoke alarms on each level and outside each separate sleeping area; hard-wired alarms may not be replaced with battery alarms","Carbon monoxide alarm near the sleeping areas (battery, hard-wired or plug-in)","The April 2026 City form no longer lists a fire extinguisher (the 2019 version did)","A Fire Prevention inspector does a walk-through inspection before the certificate is issued","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke detector and carbon monoxide alarm compliance (sale of a 1-family, 2-family or condominium unit)","amount":"$75.00"},{"label":"Same fee in the City Code fee schedule (added 2014, amended 2016 and 2019)","amount":"$75.00"}]$j$::jsonb, $t$https://www.jerseycitynj.gov/UserFiles/Servers/Server_6189660/File/City%20Hall/Public%20Safety/Fire%20Prevention/SMOKE%20CARBON%20%20CERT.pdf$t$, $t$https://www.jerseycitynj.gov/cityhall/public_safety/Fire/fireprevention/$t$, $j$[{"url":"https://www.jerseycitynj.gov/cityhall/public_safety/Fire/fireprevention/","label":"Official source (jerseycitynj.gov)"},{"url":"https://www.jerseycitynj.gov/UserFiles/Servers/Server_6189660/File/City%20Hall/Public%20Safety/Fire%20Prevention/SMOKE%20CARBON%20%20CERT.pdf","label":"Official source (jerseycitynj.gov)"},{"url":"https://api.municode.com/CodesContent?jobId=472619&nodeId=CH160FECH&productId=16093","label":"Official source (api.municode.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Prevention Office: (201) 547-4255$t$, $t$32b9f24c3bc0c5e79a635e8d152aa637ad296991c8b2e84a2e08c2203cd247b9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0906.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0906.json$t$, true),
  ($t$0907$t$, $t$Kearny$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Continued Occupancy (Certificate of Occupancy for resale), with a Zoning Permit$t$, $j$["Issued by: Town of Kearny Construction Code Enforcement Department (Construction Official/Zoning Officer)","Contact: Anthony Chisari, Construction & Zoning Official · (201) 955-7880 ext. 3005 · tchisari@kearnynj.org","Apply: No fixed number of days is published. The Town says to allow significant time before the closing date, last-minute inspections just before closing cannot be accommodated, and the checklist recommends the inspection as soon as the sales contract is signed.","How to apply: Fill out the Residential Certificate of Occupancy Package (Zoning Permit Application, Application for Zoning Certificate / Certificate of Continued Use Occupancy with the approximate closing date and purchaser details, the One and Two Family Smoke Detector and CO Detector application, and the other sheets in the package) and file it with the Construction Code Enforcement Department, Town Hall Annex, 410 Kearny Avenue, Kearny, NJ 07032, with a check or money order. Then call the front office at 201-955-7880 to schedule the inspection. Office hours Monday to Friday 8:00 am to 4:00 pm.","Smoke alarms and CO alarms within 10 feet outside each bedroom; smoke alarms must be 10-year sealed units (CO alarms may be battery or plug-in); basement and first floor alarms usually on the ceiling within 3 feet of the stair opening","Portable fire extinguisher, 2A:10B:C, no more than 10 lb, mounted within 10 feet of the kitchen in the path of egress (still listed on the Town package; see fire notes)","Cover plates on all switches, outlets and junction boxes","Handrail on any interior or exterior stair (including decks) with more than three risers, graspable and no wider than 2 5/8 inches","Pressure relief discharge pipe on heating units and water heaters, ending 6 to 8 inches above the floor","Faucets and toilets installed and working","Attached or built-in garage keeps its fire rating; door into the house fire rated and self-closing; holes from repairs patched","Sheds at least 3 feet from property lines and in good condition","Exit doors open from inside without keys; no double cylinder deadbolts","Gas piping strapped with shutoff valves near appliances, capped if an appliance was removed; no aluminum gas piping","No broken, cracked or missing glass","Guards/railings where the drop is 30 inches or more","Sidewalks, stairs, driveways and walkways in good repair","Yard clear of debris; grass, bushes and weeds cut","House numbers at least 4 inches high and visible from the street; roof, leaders, exterior walls, fences, sheds and interior surfaces in good repair","Also: Zoning Permit first: A zoning permit ($25, check or money order, no cash) must be obtained before the certificate of continued occupancy is issued.","Also: Office checks at filing: The Application for Zoning Certificate has office-use lines for open permits, monetary penalties, legal use, fire department smoke detector sign-off, state housing violations and state housing registration number.","Also: Lead-based paint (rentals only): A lead-based paint form in the package applies only if the dwelling is a rental property built before 1978; the Town does not do lead testing."]$j$::jsonb, $j$[{"label":"Residential certificate of continued occupancy, one-family dwelling (includes the smoke detector certificate)","amount":"$60.00"},{"label":"Residential certificate of continued occupancy, two-family dwelling (includes the smoke detector certificate)","amount":"$80.00"},{"label":"Residential certificate of continued occupancy, three-family or more, per dwelling unit (no smoke detector certificate needed)","amount":"$40.00/dwelling unit"},{"label":"Zoning Permit application (required before the certificate is issued); check or money order only, no cash","amount":"$25.00"}]$j$::jsonb, $t$https://www.kearnynj.org/wp-content/uploads/2024/02/Residential-CO.pdf$t$, $t$https://www.kearnynj.org/construction-code-enforcement/$t$, $j$[{"url":"https://web.archive.org/web/20221130040423/https://www.kearnynj.org/wp-content/uploads/2018/10/Land-Use-Regualtion-Chapter-36-38.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20241219062139/https://www.kearnynj.org/construction-code-enforcement/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20240724210929/https://www.kearnynj.org/forms/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20240718123420/https://www.kearnynj.org/wp-content/uploads/2024/02/Residential-CO.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20240720052151/https://www.kearnynj.org/wp-content/uploads/2023/08/Zoning-Permit-2023.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$Upon the transfer of title to any property located within the boundaries of the Town of Kearny, it shall be unlawful for any owner to occupy or permit the occupancy of that property without first obtaining a certificate of continued occupancy. This section does not apply to property transfers by inheritance.$t$, $t$ec54a9b914621cc9b7e0c0e8aec750ffadee02f046bf18bab58e073447421d7d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":5,"fee_bad":0,"fee_unchecked":1,"quotes":20,"q_ok":14,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0907.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0907.json$t$, true),
  ($t$0907$t$, $t$Kearny$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Town of Kearny Construction Code Enforcement Department (smoke/CO certificate issued by the Construction Official/Zoning Officer as part of the certificate of continued occupancy) (town fire bureau)","Contact: Anthony Chisari, Construction & Zoning Official · (201) 955-7880 ext. 3005 · tchisari@kearnynj.org","Apply: Same as the certificate of continued occupancy: allow significant time before closing; last-minute inspections cannot be accommodated.","How to apply: Submit the Application for One & Two Family Certification of Smoke Detector and Carbon Monoxide Detector Compliance as part of the Residential Certificate of Occupancy Package to the Construction Code Enforcement Department, 410 Kearny Avenue. The inspection is done by the Construction Code Department.","Fire official in the NJ state directory, updated 1/12/2026: Daniel Neves · (201) 991-1402 · dneves@kearnynj.org","Smoke alarms for resales must be 10-year sealed battery units (Town sheet says required as of January 22, 2019); A/C powered or interconnected alarms in homes built after January 1977 must be kept working","Smoke alarm on each level and outside each sleeping area within 10 feet; CO alarm outside each sleeping area within 10 feet (battery, hard-wired or plug-in, UL 2034, 85 dBA)","The Town's February 2024 package still requires a 2A:10B:C portable fire extinguisher, 10 lb or less, mounted within 10 feet of the kitchen in the path of egress and no higher than 5 feet (a 1A:10B:C unit is shown as not acceptable). The state removed the extinguisher from its requirement in February 2025 (P.L.2025, c.19); no newer Town form was found.","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide detector compliance certificate for a one-family sale, included in the certificate of continued occupancy fee","amount":"$60.00"},{"label":"Smoke and carbon monoxide detector compliance certificate for a two-family sale, included in the certificate of continued occupancy fee","amount":"$80.00"}]$j$::jsonb, $t$https://www.kearnynj.org/wp-content/uploads/2024/02/Residential-CO.pdf$t$, $t$https://www.kearnynj.org/construction-code-enforcement/$t$, $j$[{"url":"https://web.archive.org/web/20221130040423/https://www.kearnynj.org/wp-content/uploads/2018/10/Land-Use-Regualtion-Chapter-36-38.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20211228232341/https://www.kearnynj.org/wp-content/uploads/2019/01/Application-for-One-Two-Family-Certification-of-Smoke-Detector-and-Carbon-Monoxide-Detector-Compliance.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20240718123420/https://www.kearnynj.org/wp-content/uploads/2024/02/Residential-CO.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20241219062139/https://www.kearnynj.org/construction-code-enforcement/","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$When any R-3 and R-5 (use groups) (pertains to one- and two-family dwellings) property is sold, a smoke and carbon monoxide detector compliance certificate, as required by the laws of the State of New Jersey, must be obtained from the Construction Official/Zoning Officer, prior to the issuance of a certificate of [continued] occupancy.$t$, $t$f0907752ee278710c73d2464c2d0a5670c4a45aab833d0977cb4d3886329d4f8$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":5,"fee_bad":0,"fee_unchecked":1,"quotes":20,"q_ok":14,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0907.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0907.json$t$, true),
  ($t$0908$t$, $t$North Bergen Township$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Owner Certificate (residential certificate of occupancy, CCO) with buyer Affidavit for Application for Certificate of Occupancy$t$, $j$["Issued by: North Bergen Code Enforcement Office (Building/Code Enforcement/Zoning Department), Town Hall Room 208","Contact: (201) 392-2051","How to apply: Fill out the Residential Owner Certificate form (mark it as a sale; list the owner and the new owner and all occupants) and the buyer's notarized Affidavit for Application for Certificate of Occupancy, then file them with the Code Enforcement Office, Room 208, Town Hall, 4233 Kennedy Boulevard, North Bergen. The office schedules the inspection and collects the fee (amount not published online). Questions: (201) 392-2051.","Also: Buyer affidavit: The buyer must sign a notarized Affidavit for Application for Certificate of Occupancy confirming the legal number of units and agreeing not to add units without approvals."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.northbergen.org/_Content/pdf/forms/Residential-Owner-Certificate.pdf$t$, $t$https://www.northbergen.org/Departments/code-enforcement$t$, $j$[{"url":"https://www.northbergen.org/Departments/code-enforcement","label":"Official source (northbergen.org)"},{"url":"https://www.northbergen.org/Departments/commercial-business-mixed-use-and-residential-owner-certificates","label":"Official source (northbergen.org)"},{"url":"https://www.northbergen.org/_Content/pdf/forms/Residential-Owner-Certificate.pdf","label":"Official source (northbergen.org)"},{"url":"https://www.northbergen.org/_Content/pdf/forms/Affidavit-Application-Certificate-of-Occupancy.pdf","label":"Official source (northbergen.org)"},{"url":"https://www.northbergen.org/api/data/GetFormsData","label":"Official source (northbergen.org)"}]$j$::jsonb, $t$We inspect and issue commercial and residential certificates of occupancy.$t$, $t$d02914e71fa09ce5a4d9489b76d74e45d2a725712a801df2c760cbbd5b0e237e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":7,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0908.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0908.json$t$, true),
  ($t$0908$t$, $t$North Bergen Township$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: North Bergen Fire Prevention Bureau (Department of Public Safety, Fire Prevention Bureau - Code Enforcement), the local enforcing agency (town fire bureau)","Contact: Elvis Pena, Fire Official · (201) 392-2162 · FirePrev@northbergen.org","Apply: Fee depends on business days before the change of occupant: more than 10, 5 to 10, or fewer than 4.","How to apply: Fill out the Application for Smoke Detector, Carbon Monoxide & Fire Extinguisher Compliance (property, 1 or 2 family or condo, sale or rental, owner of record, realtor) and bring it with payment to the Fire Prevention Bureau, 4233 Kennedy Boulevard, to set an appointment. Pay by cash, check or money order payable to North Bergen Fire Prevention, LEA; credit cards are not accepted. Phone (201) 392-2162 or (201) 392-2075.","Fire official in the NJ state directory (town), updated 1/12/2026: Elvis Pena · (201) 392-2162 · FirePrev@northbergen.org","Smoke alarms must be ten-year sealed battery single station units (UL 217), effective January 1, 2019; A/C powered alarms from original construction must not be replaced with battery units","A/C powered smoke alarms must be tested by a licensed electrician or a certified fire alarm company, with a service report or letter given to North Bergen Fire Prevention at the inspection","Smoke alarm on each level and outside each sleeping area (no more than 10 feet); CO alarm outside each sleeping area (no more than 10 feet), UL 2034, NFPA 720","The October 2025 application is still titled Smoke Detector, Carbon Monoxide & Fire Extinguisher Compliance and the guidelines still show an extinguisher within 10 feet of the kitchen near an exit, top no higher than 5 feet, mounted on a bracket","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, carbon monoxide and fire extinguisher compliance certificate, more than 10 business days before change of occupant","amount":"$45.00"},{"label":"5 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Fewer than 4 business days before change of occupant","amount":"$161.00"},{"label":"Re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.northbergen.org/_Content/pdf/forms/APPLICATION-FOR-SMOKE-DETECTOR.pdf$t$, $t$https://www.northbergen.org/Departments/fire-prevention$t$, $j$[{"url":"https://www.northbergen.org/_Content/pdf/forms/APPLICATION-FOR-SMOKE-DETECTOR.pdf","label":"Official source (northbergen.org)"},{"url":"https://www.northbergen.org/Departments/fire-prevention","label":"Official source (northbergen.org)"},{"url":"https://www.northbergen.org/_Content/pdf/forms/SMOKE-DETECTOR-GUIDELINES.pdf","label":"Official source (northbergen.org)"},{"url":"https://www.northbergen.org/api/data/GetDirectoryDepartmentsData","label":"Official source (northbergen.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for Smoke Detector, Carbon Monoxide & Fire Extinguisher Compliance$t$, $t$bfa650d7366944c1634b4f7d48b5f6d5426988842ecd6d99b2ad2490541d22cc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":7,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0908.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0908.json$t$, true),
  ($t$0909$t$, $t$Secaucus$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Sale/Rental Certification (Residential and Mixed Uses)$t$, $j$["Issued by: Town of Secaucus Construction Department","Contact: Carl Leppin, Construction Official / Fire Subcode Official · (201) 330-2027 · cleppin@secaucus.net","Apply: Town recommends scheduling the inspection two weeks before the real estate closing; an extra fee applies if the inspection is needed in less than 10 days.","How to apply: Fill out the Application for Sale/Rental Certification (Residential and Mixed Uses): check Sale of Property, give the new buyer, realtor and closing date, and sign. File it with the Construction Department with a check or money order. The website lists the office at the Town Hall Annex, 20 Centre Ave, First Floor (the form header still shows 1203 Paterson Plank Road, 4th Floor). Phone (201) 330-2027, Monday-Friday 9am-4pm.","Water heaters, boilers, furnaces, HVAC and other electric or fuel-burning appliances in good working order, free of obvious hazards, with finalized permits","All open permits finalized before the certification is issued","Hot and cold water working in kitchens, bathrooms and laundry areas","Temperature/pressure relief valve discharge piped to within 6 inches of the floor and not threaded at the end","Main electrical service secured to the building with approved straps","Cover plates on all outlets, switches and junction boxes; no exposed wiring; installed GFCI outlets and breakers working","No open breaker slots in electrical panels; panels readily accessible","No extension cords used in place of permanent wiring","No open or partly exposed bulb incandescent fixtures in clothes closets","Handrails on all stairways and steps with four or more risers","Sump pump pits covered; sump pumps may not discharge into the sanitary sewer","Basement rooms used as bedrooms may need properly sized egress windows","Property must conform to all Town zoning and planning ordinances","Also: Open permits: All open permits must be finalized before the Sale/Rental Certification is issued.","Also: Lead-based paint inspection: Certain pre-1978 residential structures need a lead-based paint inspection; $50 fee if needed.","Also: Zoning conformity: The property must conform to all Town zoning and planning ordinances."]$j$::jsonb, $j$[{"label":"Sale/Rental Certification inspection, sale of one family","amount":"$100"},{"label":"Sale/Rental Certification inspection, sale of two family","amount":"$125"},{"label":"Expedited inspection (completed in less than 10 days), added to the certification fee","amount":"Additional $50"},{"label":"After 3 scheduled inspections are failed or missed, each additional inspection","amount":"$37"},{"label":"Lead-based paint inspection, if needed (certain pre-1978 structures)","amount":"$50"},{"label":"Lead-based paint inspection, expedited (less than 10 days); printed right after the lead paint fee line","amount":"Additional $30"},{"label":"Lead-based paint inspection, after 3 failed or missed inspections, each additional; printed right after the lead paint fee line","amount":"$30"}]$j$::jsonb, $t$https://secaucusnj.gov/forms-documents/forms/department-documents/construction/1369-residential-sale-rental-certification-application/file$t$, $t$https://secaucusnj.gov/departments/construction$t$, $j$[{"url":"https://web.archive.org/web/20251223165329/https://www.secaucusnj.gov/forms-documents/forms/department-documents/construction/1369-residential-sale-rental-certification-application/file","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20251222031953/https://www.secaucusnj.gov/forms-documents/forms/department-documents/construction/1370-residential-sale-rental-certification-checklist/file","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260914132147/https://secaucusnj.gov/departments/construction","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$APPLICATION FOR SALE/RENTAL CERTIFICATION (RESIDENTIAL AND MIXED USES)$t$, $t$d7c0d6a7ba362423dd6723f47eec00a206402453ca4c4c17a5a6b6f7fa2e5353$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":4,"fee_bad":0,"fee_unchecked":7,"quotes":18,"q_ok":9,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0909.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0909.json$t$, true),
  ($t$0909$t$, $t$Secaucus$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Secaucus Bureau of Fire Prevention (Secaucus Fire Department local enforcing agency) (town fire bureau)","Contact: Vincent Massaro, Fire Official · (201) 330-2000 x 3170 · vmassaro@secaucus.net","Apply: The office contacts you within 48 hours of receiving the request to schedule; a higher fee applies if the inspection date is within 4 days or less.","How to apply: Fill out the Residential Inspection Request Form (Smoke Alarm, Carbon Monoxide Alarm, Fire Extinguisher Compliance) and mail or bring it with a check or money order payable to \"TOWN OF SECAUCUS\" to the Bureau of Fire Prevention, Municipal Government Center, 1203 Paterson Plank Road, Second Floor. The office calls within 48 hours to schedule. Office hours Monday to Friday 9:00 AM to 4:00 PM.","Fire official in the NJ state directory, updated 9/8/2025: Vincent Massaro · (201) 330-2059 · vmassaro@secaucus.net","If the home is connected to a central monitoring system, show proof (company paperwork) that the alarm system is in proper working order","An adult must be at the home at the time of the inspection; inspections are between 9:30 AM and 2:30 PM","The Town form (updated 2018) still attaches the old state rule text requiring a 2A-10B:C portable fire extinguisher within 10 feet of the kitchen, serviced and tagged within 12 months or with a recent purchase receipt; the state dropped the extinguisher in February 2025 and no newer Town form was found","Ten-year sealed battery smoke alarms (per the state rule text attached to the form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, carbon monoxide alarm and fire extinguisher compliance inspection, single family residence","amount":"$50.00"},{"label":"Two family residence","amount":"$75.00"},{"label":"Inspection date within 4 days or less","amount":"$200.00"},{"label":"Re-inspection (failed inspection or inspector must return)","amount":"$40.00"}]$j$::jsonb, $t$https://secaucusnj.gov/forms-documents/forms/department-documents/fire-prevention/288-smoke-detector-inspection-request-form-updated-2018/file$t$, $t$https://secaucusnj.gov/departments/fire-prevention$t$, $j$[{"url":"https://web.archive.org/web/20250810075946/https://secaucusnj.gov/forms-documents/forms/department-documents/fire-prevention/288-smoke-detector-inspection-request-form-updated-2018/file","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260611134421/https://secaucusnj.gov/departments/fire-prevention","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$RESIDENTIAL INSPECTION REQUEST FORM$t$, $t$4f3e867af1acca9b95309085d238c41f511f246bd82f9592b2556298fc747247$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":4,"fee_bad":0,"fee_unchecked":7,"quotes":18,"q_ok":9,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0909.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0909.json$t$, true),
  ($t$0912$t$, $t$West New York$t$, $t$HUDSON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Owner Certificate (Ownership Certificate, Town Code Chapter 148 "Certificates of Occupancy")$t$, $j$["Issued by: Town of West New York Code Enforcement / Building Department (Director of Public Affairs or designee, or the Construction Code Official), with a Fire Prevention Residential Ownership Review","Contact: Tom O'Malley, Construction Official · 201-295-5173 · tomomalley@westnewyorknj.org","How to apply: Fill out the Residential Owner Certificate application (anticipated closing date, present owner and purchasers; LLCs must name the manager or principal). The purchaser signs the Certification/Affidavit on page 2 in front of a notary, and the applicant meets with the Fire Prevention office for the Fire Prevention Residential Ownership Review on page 3. File with the Code Enforcement / Building Department, Municipal Building, 428-60th Street, Office No. 27, with the fee payable to Town of West New York.","Boilers/furnaces: a full fire-rated ceiling or a sprinkler installed on the code water line","All final inspections on any permits finalized","Egress free and clear; inspector must have entry to all areas of the property","Exit doors free of padlocks and key locks; exit signs and emergency lighting working where present","Fire extinguisher within ten feet of any kitchen, properly mounted and readily accessible","Handrails on all stairs with 3 or more risers plus landings, interior and exterior","No keyed locks on any interior doors","Smoke detectors and carbon monoxide alarms","Sprinklers operating properly (where present)","No trash or rubbish accumulation inside or outside","No outstanding building code or property maintenance violations","Windows operable, no broken or cracked glass","Also: Purchaser affidavit: The purchaser must sign a notarized Certification/Affidavit stating the number of dwelling units and agreeing to follow the Hotel and Multiple Dwelling Law and local codes if units change.","Also: Fire Prevention Residential Ownership Review: The applicant meets with the WNY Fire Prevention office, which marks whether the property does or does not require approvals from that office for the title transfer.","Also: Temporary certificate for as-is sales: If violations will not be corrected before closing, a nonrenewable temporary ownership certificate of up to six months may be issued; the as-is agreement must be attached and the application signed by seller and buyer."]$j$::jsonb, $j$[{"label":"Residential Owner Certificate, one to two unit dwellings","amount":"$100.00"},{"label":"Residential Owner Certificate, condominium and co-op units","amount":"$100.00"},{"label":"Reinspection, per unit, for each additional inspection","amount":"$50.00"},{"label":"Ownership certificate fee in the 2016 ordinance, condominiums, co-ops and one and two family buildings","amount":"$100"},{"label":"Letter confirming issuance of a certificate of occupancy or owners certificate (2016 fee ordinance)","amount":"$50"}]$j$::jsonb, $t$https://www.westnewyorknj.org/wp-content/uploads/2025/12/RESIDENTIAL-OWNER-CERTIFICATE-APPLICATION-3.pdf$t$, $t$https://www.westnewyorknj.org/departments/building-department/$t$, $j$[{"url":"https://web.archive.org/web/20231209124737/https://www.westnewyorknj.org/wp-content/uploads/2023/11/ord616.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260424234305/https://www.westnewyorknj.org/wp-content/uploads/2025/12/RESIDENTIAL-OWNER-CERTIFICATE-APPLICATION-3.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260831104043/https://www.westnewyorknj.org/departments/building-department/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20231210225000/https://www.westnewyorknj.org/wp-content/uploads/2023/11/ord516.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$It shall henceforth be unlawful for any owner or prospective purchaser of real property to sell, convey, delivery or transfer, and for any purchaser to purchase, take title or possession of, any residential building or premises until an ownership certificate, to the effect that such residential building or premise complies with and conforms to the provisions of this article, shall have been issued by the Director of the Department of Public Affairs or his designee.$t$, $t$bc47ebacb3913ea4edd4d44e0f2ade80f63af814d1c29714267e4f04bbbaf9c4$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":4,"fee_bad":0,"fee_unchecked":3,"quotes":20,"q_ok":17,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0912.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0912.json$t$, true),
  ($t$0912$t$, $t$West New York$t$, $t$HUDSON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: West New York Office of Fire Prevention (WNY Bureau of Fire Safety), the local enforcing agency for non-life-hazard uses (town fire bureau)","Contact: Robert Torres Jr., Fire Official · 201-295-5221 · rtorres@westnewyorknj.org","How to apply: Fill out the Application for One & Two Families, Condos, Co-ops & Rental Certification of Smoke Detector & Carbon Monoxide Alarm (with the closing date and who will be present) and pay by check or money order payable to \"WNY BUREAU OF FIRE SAFETY\". The form also includes a notarized Application and Certification in Lieu of Inspection. Office of Fire Prevention, 6015 Tyler Place, 201.295.5220, 9 AM to 4 PM.","Fire official in the NJ state directory (NJ DCA, state), updated 1/12/2026: Louis Kilmer · (609) 633-6132","Smoke detectors must be 10-year sealed by the manufacturer (since January 1, 2019); AC powered or interconnected alarms in homes after January 1977 must be kept working","The 2025 Town forms still require a portable fire extinguisher: minimum 2A:10B:C, no more than 10 pounds, within 10 feet of the kitchen in the exit path, top no more than 5 feet above the floor, mounted on the maker's bracket, with the owner's manual, serviced and tagged by a DFS-certified contractor within 12 months or a recent purchase receipt","Smoke detector certificates are valid for six months; if the change of occupant does not happen within 6 months a new application is needed","A notarized application and certification in lieu of inspection is offered; the Fire Prevention Bureau may do a follow-up inspection within 12 months","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke detector and carbon monoxide alarm compliance, change of occupant (flat fee)","amount":"$150.00"},{"label":"Re-inspection if the inspection fails","amount":"$20.00"}]$j$::jsonb, $t$https://www.westnewyorknj.org/wp-content/uploads/2025/02/FirePrevention_SmokeDetectorApplication-002.pdf$t$, $t$https://www.westnewyorknj.org/departments/fire-prevention/$t$, $j$[{"url":"https://web.archive.org/web/20250426134502/https://www.westnewyorknj.org/wp-content/uploads/2025/02/FirePrevention_SmokeDetectorApplication-002.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20250723182559/https://www.westnewyorknj.org/wp-content/uploads/2025/05/FirePrevention_Checklist_2025.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260607112149/https://www.westnewyorknj.org/departments/fire-prevention/","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$APPLICATION FOR ONE & TWO FAMILIES, CONDOS, CO-OPS, & RENTAL CERTIFICATION OF SMOKE DETECTOR & CARBON MONOXIDE ALARM$t$, $t$ca2de7b32a814b72ea7807ca6df050442d66d63e4d086a42f775d5c413d6bf67$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":4,"fee_bad":0,"fee_unchecked":3,"quotes":20,"q_ok":17,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0912.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0912.json$t$, true),
  ($t$1102$t$, $t$Ewing Township$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Property Transfer (Resale) Inspection$t$, $j$["Issued by: Division of Housing, Ewing Township Code Enforcement Office (Construction Office)","Contact: Lisa Litz, Office Supervisor (Housing, Rental, Property Transfer) · (609) 883-2900 · llitz@ewingnj.org","How to apply: Fill out the Property Transfer Resale Application (owner, buyer, property details and the number of smoke and CO detectors) and submit it with the fee to the Ewing Construction Office, 1666 Pennington Rd. (rear of building), Ewing. The form has boxes for cash, check or credit card, and asks whether the certificate should be picked up, mailed or emailed. The form says an LLC seller or buyer must also list the owner's name. Inspections can also be requested and tracked on the Township's SDL Portal (account needed).","Exterior property: sanitation, grading and drainage, sidewalks and driveways, weeds, rodent harborage, garage, shed, fences and walls, motor vehicles","Exterior structure: doors, windows, trim and porches, street numbers, foundation, roof and drains, chimneys, stairs and decks, working windows and insect screens","Interior: structural members, stairs, railings and handrails, rubbish and garbage storage, insect or rodent infestation, lighting and ventilation","Plumbing: fixtures, water system, drainage, water pressure and hot water temperature","Heating and mechanical equipment, combustion air and clearances","Electrical: at least 2 receptacles per bedroom and GFCI outlets in kitchen, bath and outdoors","Smoke alarm on every level (10 year lithium sealed battery single station alarms)","Carbon monoxide alarm within 10 feet of sleeping areas","No double-keyed deadbolts","Well water certificate if the home has a well","All open permits must be closed out; some repairs may need construction (UCC) permits","A Tax Assessor representative comes to the home on the day of the inspection","Also: Open permits: All open permits must be closed out; some repairs may require construction (UCC) permits.","Also: Well water certificate: A well water certificate will be required if applicable."]$j$::jsonb, $j$[{"label":"Property transfer resale inspection, single family dwelling","amount":"$125.00"},{"label":"Property transfer resale inspection, multi-dwelling, per unit","amount":"$125.00 Per Unit"},{"label":"Property or tenant transfer inspection, residential (2025 info form)","amount":"$125.00"}]$j$::jsonb, $t$https://ewingnj.org/documents-list/department-documents/housing/561-property-resale-transfer-application/file$t$, $t$https://ewingnj.org/housing$t$, $j$[{"url":"https://ewingnj.org/housing","label":"Official source (ewingnj.org)"},{"url":"https://ewingnj.org/construction-staff","label":"Official source (ewingnj.org)"},{"url":"https://ewingnj.org/documents-list/department-documents/housing/561-property-resale-transfer-application/file","label":"Official source (ewingnj.org)"},{"url":"https://ewingnj.org/documents-list/department-documents/housing/638-property-tenant-transfer-inspection-info-form-2025-002/file","label":"Official source (ewingnj.org)"}]$j$::jsonb, $t$All dwellings or commercial buildings being offered for resale in Ewing Township must be inspected and approved by the Division of Housing.$t$, $t$1235a2995220cea162ac2fca995034b308146de7821339dfd0c6b559fe91cefe$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1102.json$t$, true),
  ($t$1102$t$, $t$Ewing Township$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Ewing Township Fire Prevention (municipal local enforcing agency); smoke and CO alarms are also checked in the Division of Housing property transfer inspection (town fire bureau)","Contact: Chad Hutchinson, Acting Fire Marshal · (609) 882-9885 x112 · chutchinson@ewingnj.org","How to apply: No separate smoke and carbon monoxide certificate application or fee is posted. The Housing resale application asks for the number of smoke and CO detectors, and the property transfer information form lists smoke and CO alarms among the items inspected. Call Fire Prevention or the Code Enforcement Office to confirm whether the certificate is issued with the resale inspection or needs its own request and fee.","Fire official in the NJ state directory (town), updated 1/26/2026: Chad Hutchinson · (609) 882-9885 · chutchinson@ewingnj.org","Ten-year sealed battery single station smoke alarms are required for any residential property transfer","Hardwired (A.C. powered) smoke alarms may not be replaced with battery alarms","The 2025 property transfer information form says a fire extinguisher is no longer required for residential properties","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://ewingnj.org/fireprevention$t$, $j$[{"url":"https://ewingnj.org/fireprevention","label":"Official source (ewingnj.org)"},{"url":"https://ewingnj.org/documents-list/department-documents/housing/561-property-resale-transfer-application/file","label":"Official source (ewingnj.org)"},{"url":"https://ewingnj.org/documents-list/department-documents/housing/638-property-tenant-transfer-inspection-info-form-2025-002/file","label":"Official source (ewingnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Acting Fire Marshal Chad Hutchinson p: (609) 882-9885 x112 email: chutchinson@ewingnj.org$t$, $t$978436bb6155c7f922f96cc1be5dead99fc1712992e31e9c5789cff42162a7d6$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1102.json$t$, true),
  ($t$1103$t$, $t$Hamilton Township$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Approval for Occupancy (Change of Occupancy, Sale)$t$, $j$["Issued by: Division of Housing & Landlord Compliance (Housing Inspection & Landlord Compliance Office)","Contact: Richard Merger, Chief Housing Inspector · 609-890-3665 · HousingHT@HamiltonNJ.com","How to apply: Apply online through the Change of Occupancy Application Portal, or fill out the Certificate of Approval for Occupancy Sale Application for Single Family Property and submit it to the Office of Housing Inspections, 2090 Greenwood Avenue, Room 302, Hamilton. Only the owner, the owner's realtor, the owner's attorney or a power of attorney may apply. Pay by cash, credit card or check. Inspections are scheduled in a morning (9:30 to noon) or afternoon (1:00 to 3:30) window.","Working smoke detectors not more than 10 years old; battery-only units must have 10 year sealed batteries, and hardwired units need battery backup","Working carbon monoxide detectors within 10 feet of all sleeping rooms","Portable fire extinguisher (at least 1A:10B:C, no more than 10 pounds) mounted in or within 10 feet of the kitchen (checklist dated April 2026)","Walls, ceilings, floors and bathroom tiles in good repair; bathroom doors lock","Working hot and cold water with shut off valves, secured toilets, approved drain traps","Stove and oven work and ranges have an anti-tilt bracket","GFCI outlets within 6 feet of water (bathroom, kitchen, unfinished basement); no extension cords in place of wiring","Water heater and boiler in good order; relief valve discharge pipe 2 to 6 inches from the floor; gas shut off valve on each gas appliance","Roof and structure sound; chimneys safe; fireplaces and wood stoves need a Level II chimney certification","No double-keyed deadbolts on exit doors; no keyed bedroom locks; windows open, lock and have screens","Handrails and guards on stairs, porches and decks; fences and pool barriers in good repair","House numbers at least 3 inches high, visible from the curb; grass cut, no rodents or insects","Sump pumps discharge outside and not into the sanitary sewer","Work done without permits must be permitted and inspected, and open construction permits must be closed","Well and septic systems must be approved by the Health Department","Also: Open construction permits: Open construction permits must be closed before the Certificate of Occupancy can be issued; work done without permits must be permitted and inspected.","Also: Well and septic: Well and septic systems must be approved by the Health Department before the certificate is issued.","Also: Fireplaces and wood stoves: A Level II certification from a qualified chimney sweep company is required for fireplaces and wood burning stoves."]$j$::jsonb, $j$[{"label":"Certificate of Approval for Occupancy, sale of a single family property","amount":"$200.00"}]$j$::jsonb, $t$https://www.hamiltonnj.com/DocumentCenter/View/2813/Change-of-Occupancy-Application-for-Single-Family-Property-PDF$t$, $t$https://www.hamiltonnj.com/HousingInspections$t$, $j$[{"url":"https://www.hamiltonnj.com/HousingInspections","label":"Official source (hamiltonnj.com)"},{"url":"https://www.hamiltonnj.com/DocumentCenter/View/2813/Change-of-Occupancy-Application-for-Single-Family-Property-PDF","label":"Official source (hamiltonnj.com)"},{"url":"https://www.hamiltonnj.com/DocumentCenter/View/564/Change-of-Occupancy-Checklist-PDF","label":"Official source (hamiltonnj.com)"}]$j$::jsonb, $t$Prior to any change in occupancy of any house, dwelling, dwelling unit, or apartment unit which is used, partially used, or intended to be used for human occupancy, a certificate of approval shall first have been obtained from the office of Housing Inspections$t$, $t$1f6fcf5a6c2f41d143a6b439f9ad38cdf7e097f9a94bbf87675e5f9206c0ab09$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1103.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1103.json$t$, true),
  ($t$1103$t$, $t$Hamilton Township$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hamilton Township Division of Housing & Landlord Compliance (smoke detector compliance for the Township fire code agency) (town fire bureau)","Contact: Richard Merger, Chief Housing Inspector · 609-890-3665 · HousingHT@HamiltonNJ.com","How to apply: For owner-occupied 1 and 2 family homes the smoke, carbon monoxide and fire extinguisher items are checked in the Housing change of occupancy inspection (see the Change of Occupancy Checklist). No separate smoke certificate application or fee is posted. Apply for the Certificate of Approval for Occupancy through the Housing office or its online portal and ask whether the smoke and CO certificate is issued with it.","Fire official in the NJ state directory (town), updated 8/1/2013: Scott McCormick · (609) 890-6927 · smccormick@hamiltonfirenj.org","Smoke detectors not more than 10 years old; battery-only units must have 10 year sealed batteries; hardwired units need replaceable or 10 year sealed battery backup","Carbon monoxide detectors within 10 feet of all sleeping rooms","The April 2026 Change of Occupancy Checklist still lists a portable fire extinguisher (at least 1A:10B:C, no more than 10 pounds) mounted in or within 10 feet of the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.hamiltonnj.com/DocumentCenter/View/2813/Change-of-Occupancy-Application-for-Single-Family-Property-PDF$t$, $t$https://www.hamiltonnj.com/HousingInspections$t$, $j$[{"url":"https://www.hamiltonnj.com/DocumentCenter/View/564/Change-of-Occupancy-Checklist-PDF","label":"Official source (hamiltonnj.com)"},{"url":"https://www.hamiltonnj.com/578/Fire-Prevention-Bureau","label":"Official source (hamiltonnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detectors: All dwelling units are required to be equipped with working smoke detectors. Smoke detectors shall not be more than 10 years old.$t$, $t$8667b13abf4e7e8b63e9596074852332e4bab1b82b1f9b77857ae511bb942519$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1103.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1103.json$t$, true),
  ($t$1104$t$, $t$Hightstown Borough$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance, Sale/Title Transfer$t$, $j$["Issued by: Code Enforcement Office (Housing Inspector)","Contact: Dave Bell, Housing Inspector · (609) 490-5100 Ext 407 · DBell@HightstownBorough.com","Apply: Apply at least 10 business days before closing for the lowest fee","How to apply: Fill out the Application for Certificate of Compliance, Sale/Title Transfer (closing date, owner, agent, buyer names) and submit it with the fee and the required furnace or boiler certification (and Level 2 chimney certification if there is a wood-burning fireplace) to the Code Enforcement Office, 156 Bank Street, Hightstown. Cash or check only, payable to Borough of Hightstown. The Borough then calls to schedule the inspection; a lockbox code may be given for a vacant home. The form can also be emailed to DBell@HightstownBorough.com.","Smoke detectors on each level and outside each sleeping area (10 year sealed or hardwired)","Carbon monoxide detector near all sleeping areas (less than 10 years old)","ABC fire extinguisher mounted within 10 feet of the kitchen, no larger than 10 pounds (as printed on the form)","Windows open and stay open","GFCI outlets where required, working properly","Metal dryer vent connector, not plastic","No garbage disposal (not allowed by Borough ordinance)","Sump pump discharge meets Borough ordinance","Sidewalks and curbs in good condition","Permits obtained for all work (plumbing, electric, furnace, water heater, etc.); open permits may delay the certificate","Furnace or boiler certification or checklist by a licensed HVAC or plumbing contractor","Level 2 chimney certification by a nationally certified chimney sweep for a wood-burning fireplace","Also: Furnace or boiler certification: Furnace/Boiler certification or checklist completed by a licensed HVAC or plumbing contractor must be submitted with the application.","Also: Chimney certification: Level 2 wood-burning fireplace chimney certification by a nationally certified chimney sweep, if there is a wood-burning fireplace.","Also: Open permits: Open permits may delay the Certificate of Compliance; permits must have been obtained for all work."]$j$::jsonb, $j$[{"label":"Certificate of Compliance, submitted at least 10 business days before closing","amount":"$150"},{"label":"Certificate of Compliance, submitted less than 10 business days before closing","amount":"$200"},{"label":"Certificate of Compliance, submitted less than 5 business days before closing","amount":"$250"},{"label":"Reinspection","amount":"$75"}]$j$::jsonb, $t$https://www.hightstownborough.com/wp-content/uploads/2026/04/2026-CC-for-Sale-Transfer-Application-Rev-3.26.pdf$t$, $t$https://www.hightstownborough.com/construction-zoning/$t$, $j$[{"url":"https://www.hightstownborough.com/wp-content/uploads/2026/04/2026-CC-for-Sale-Transfer-Application-Rev-3.26.pdf","label":"Official source (hightstownborough.com)"},{"url":"https://www.hightstownborough.com/construction-zoning/","label":"Official source (hightstownborough.com)"},{"url":"https://www.hightstownborough.com/forms-and-permits/","label":"Official source (hightstownborough.com)"}]$j$::jsonb, $t$APPLICATION for CERTIFICATE of COMPLIANCE SALE/TITLE TRANSFER$t$, $t$b7a910bf85b3c03a8ffc55441a443b1cb5256ecebec7c6f646aa9b3a5e1f48fe$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1104.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1104.json$t$, true),
  ($t$1104$t$, $t$Hightstown Borough$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hightstown Borough Code Enforcement / Construction Office (smoke detector compliance for the Borough fire code agency) (town fire bureau)","Contact: Dave Bell, Housing Inspector · (609) 490-5100 Ext 407 · DBell@HightstownBorough.com","How to apply: No separate smoke and carbon monoxide certificate form is posted. The smoke detector, CO detector and fire extinguisher items are on the inspection checklist of the Certificate of Compliance for Sale/Title Transfer application, so they appear to be checked in that inspection. Confirm with the Code Enforcement Office or the Fire Official whether a separate certificate or fee applies.","Fire official in the NJ state directory (town), updated 6/10/2022: Chad Reed · (609) 490-5100 · Fireprevention@hightstownborough.","Smoke detectors on each level and outside each sleeping area, 10 year sealed battery or hardwired","Carbon monoxide detector near all sleeping areas, less than 10 years old","The Borough sale form still lists an ABC fire extinguisher within 10 feet of the kitchen (form footer Revised: 01/2025, after the February 2025 state change)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.hightstownborough.com/wp-content/uploads/2026/04/2026-CC-for-Sale-Transfer-Application-Rev-3.26.pdf$t$, $t$https://www.hightstownborough.com/construction-zoning/$t$, $j$[{"url":"https://www.hightstownborough.com/wp-content/uploads/2026/04/2026-CC-for-Sale-Transfer-Application-Rev-3.26.pdf","label":"Official source (hightstownborough.com)"},{"url":"https://www.hightstownborough.com/construction-zoning/","label":"Official source (hightstownborough.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detectors on each level and outside each sleeping area. (10-year sealed or hard-wired)$t$, $t$3230583ef221b3fe7d081648d9cafb3bd23e84250b7f08d58455ef20d3c7b917$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1104.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1104.json$t$, true),
  ($t$1107$t$, $t$Lawrence Township$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (Property Transfer Application, Division of Housing)$t$, $j$["Issued by: Township of Lawrence Division of Housing (Housing Bureau)","Contact: Kelly Barkalow, Fire Prevention Specialist, Division of Housing · 609-844-7032 · kbarkalow@lawrencetwp.com","Apply: Apply as soon as possible after listing; the Township says the current wait for an inspection is about 3-4 weeks (its FAQ says generally within two weeks). No expediting.","How to apply: Fill out the Property Transfer Application and bring or mail it with the $80.00 fee to the Division of Housing, 2207 Lawrence Road (Lawrenceville Road), Lawrence Township, NJ 08648. Faxed or emailed applications are not accepted. Pay by check (payable to Township of Lawrence), exact cash, money order, or Visa/Mastercard credit in the office only. After the application and fee are received, the owner or agent calls the Division of Housing (609-844-7032) to schedule. An adult must be present if occupied; a vacant home with a lockbox can be inspected with the lockbox code. The certificate is typed the next business day and mailed or picked up (not emailed or faxed).","Valid for: One year from the original inspection date","Smoke alarms as required for the year the home was built (hard-wired, interconnected alarms for newer homes); battery-only alarms must be 10-year sealed units","Smoke alarms older than 10 years must be replaced","Carbon monoxide alarm within 10 feet of the bedroom doors (or one in each bedroom)","Secondary power source label (generators, solar, batteries) within 18 inches of the main electrical panel and meter, not handwritten","Fire extinguisher is checked during the housing inspection (per the Housing FAQ; the February 2026 checklist no longer lists it)","Dryer vents must be aluminum flex, not plastic","Sump pumps must discharge outdoors, not into the sewer","Private well: well test report under the NJ Private Well Testing Act sent to the Division of Housing","Septic system: NJDEP-protocol septic inspection reviewed and approved by the Health Department before the certificate is issued","A failed septic system or outstanding permits must be addressed by the current owner before closing","Life safety violations must be corrected and reinspected before anyone moves in; a buyer may assume most other violations in writing","Also: Open permits: Outstanding permits must be addressed by the current owner before closing; the application has an Outstanding Permits section. The checklist also tells buyers to verify there are no open permits (records requests go to the Municipal Clerk).","Also: Septic system: A NJDEP-protocol septic inspection (N.J.A.C. 7:9A-12.6) must be reviewed and approved by the Health Department before the Certificate of Inspection is issued; a failed septic system must be addressed by the current owner before closing.","Also: Private well test: Homes with a private well must be tested under the NJ Private Well Testing Act; the report should be sent to the Division of Housing.","Also: Buyer assumption of violations: A buyer may assume most violations with the Assumption of Violations by Buyer letter; life hazard violations must be corrected and reinspected before occupancy."]$j$::jsonb, $j$[{"label":"Certificate of Inspection for a sale (single or two family)","amount":"$80.00"},{"label":"Housing Inspection Fee (Township fee ordinance 2495-25, adopted May 20, 2025)","amount":"$80.00"}]$j$::jsonb, $t$https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Property%20Transfer%20Application$t$, $t$https://www.lawrencetwp.com/departments/division-of-housing$t$, $j$[{"url":"https://www.lawrencetwp.com/HousingFAQ","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/departments/division-of-housing","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Property%20Transfer%20Application","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Housing%20Pre%20Inspection%20Checklist","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Ordinances/2025/2495.25.pdf","label":"Official source (lawrencetwp.com)"}]$j$::jsonb, $t$If I am selling my home/condo do I need to get a Certificate of Inspection? Yes, a Certificate of Inspection is required prior to the transfer of ownership.$t$, $t$4815dd030f669958854b18900360629475f29763c514ae0ce6e5c2be617ebc89$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":22,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1107.json$t$, true),
  ($t$1107$t$, $t$Lawrence Township$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Lawrence Township Fire Marshal's Office (municipal fire code enforcing agency); the resale smoke/CO check is done by the Township housing inspector (town fire bureau)","Contact: Edward Tencza, Fire Official · 609-844-7021 · ETencza@lawrencetwp.com","Apply: Part of the housing inspection (currently about 3-4 weeks wait)","How to apply: For a sale, file the Division of Housing Property Transfer Application ($80.00); the housing inspector checks smoke alarms, CO alarms and the extinguisher under the Fire Marshal's oversight. Questions: Division of Housing 609-844-7032 or Fire Marshal's Office 609-844-7018, 2207 Lawrenceville Road.","Fire official in the NJ state directory (town), updated 1/9/2026: Edward C Tencza · (609) 844-7021 · ETencza@lawrencetwp.com","No separate smoke/CO certificate for a sale: smoke alarms, CO alarms and the fire extinguisher are inspected during the Division of Housing inspection and included in the Certificate of Inspection","Battery-only smoke alarms must be 10-year sealed units; alarms over 10 years old must be replaced","Secondary power source warning label within 18 inches of the main panel and meter (homes with generators, solar or batteries)","Low-voltage monitored systems are supplemental; originally required alarms must be put back if removed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Included in the $80.00 Certificate of Inspection (no separate certificate needed for a sale)","amount":"$80.00"},{"label":"Separate Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance, application received 10 or more business days before change of occupant (printed as '-10'; fee schedule in Ordinance 2495-25, not charged on a sale per the…","amount":"$45.00"},{"label":"Separate Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance, application received 4-10 business days before change of occupant (Ordinance 2495-25)","amount":"$90.00"},{"label":"Separate Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance, application received fewer than 4 business days before change of occupant (Ordinance 2495-25)","amount":"$161.00"}]$j$::jsonb, $t$https://www.lawrencetwp.com/media/Departments/Housing/Housing%20Forms/Property%20Transfer%20Application$t$, $t$https://www.lawrencetwp.com/departments/firemarshal$t$, $j$[{"url":"https://www.lawrencetwp.com/HousingFAQ","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/departments/firemarshal","label":"Official source (lawrencetwp.com)"},{"url":"https://www.lawrencetwp.com/media/Ordinances/2025/2495.25.pdf","label":"Official source (lawrencetwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Is a separate smoke alarm and carbon monoxide detector certificate required? No, a separate certificate is not required. The smoke alarms, carbon monoxide detectors, and fire extinguishers are inspected during the housing Inspection and included as part of the Certificate of Inspection$t$, $t$7f5a43424511b3d24bdc09f7ff5ad1cb8c0095ff1b0c0eeb930f2ae2bd46c0f3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":22,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1107.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1107.json$t$, true),
  ($t$1108$t$, $t$Pennington Borough$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Pennington Borough. Confirm with the office if the buyer's lender or title company asks.","Contact: Rick Smith, Superintendent of Public Works (schedules the pre-closing water and sewer House Inspection) · 609-737-9440 · publicworks@penningtonboro.org","How to apply: No Borough Certificate of Occupancy is needed for a sale. Separately, the Borough requires a Department of Public Works water and sewer House Inspection before closing (see the \"Also\" lines) and a final meter read.","Also: Water and sewer House Inspection by the Department of Public Works (required before closing): Schedule at least ten business days before closing with Superintendent of Public Works Rick Smith, 609-737-9440. The Water/Sewer page says: 'There is a fee of $100 that must be either mailed or dropped off at Borough Hall before the inspection.' The Home Sale Checklist instead says the House Inspection fee is charged to the final water/sewer bill. Ordinance 2026-19 (introduced May 4, 2026; adoption not confirmed) sets 'House inspections on sale of property: regular fee' at $200 (was $150) and $300 (was $250) with less than 10 days' notice.","Also: House inspection fee in Ordinance 2026-19 (introduced May 4, 2026): Quote: \"House inspections on sale of property: regular fee, $150 $200; fee if less than 10 days' notice, $250 $300 .\" In the ordinance, $150 and $250 are struck out and $200 and $300 are underlined (new).","Also: Final water meter read: Once there is a closing date, email Gabrielle Smith, DPW (publicworks@penningtonboro.org), with the title company name. A non-quarterly meter read fee is charged to the final water/sewer bill (Ordinance 2026-19 proposes $100 scheduled, up from $75)."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.penningtonboro.org/1239/Borough-Home-Sale-Checklist$t$, $j$[{"url":"https://www.penningtonboro.org/1239/Borough-Home-Sale-Checklist","label":"Official source (penningtonboro.org)"},{"url":"https://www.penningtonboro.org/DocumentCenter/View/1717/Sale-of-Home","label":"Official source (penningtonboro.org)"},{"url":"https://www.penningtonboro.org/1242/WaterSewer","label":"Official source (penningtonboro.org)"}]$j$::jsonb, $t$The Borough does not require a Certificate of Occupancy for the sale of a residential property.$t$, $t$b2cb52875e3182748e1d4c04d82e78c6f8a9fb9f07bb039004a8dc309d012587$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1108.json$t$, true),
  ($t$1108$t$, $t$Pennington Borough$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency and issues smoke certificates in Pennington) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official for Pennington in the state directory (Bureau Chief, Bureau of Fire Code Enforcement) · 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply and pay online through the NJ DCA Fire Safety Service Portal ('Start Your Smoke Certification Application'), as the Borough checklist directs. Pay by e-check or credit card before submitting; a valid email is required and the certificate is emailed once the fee is paid and any required inspection is done. Homes heated only by electricity with no attached garage (no CO alarm needed) should email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 6/4/2026: Louis Kilmer · (609) 633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Application more than 10 business days before closing","amount":"$45"},{"label":"Application 4 to 10 business days before closing","amount":"$90"},{"label":"Application less than 4 business days before closing","amount":"$161"},{"label":"State rule: request received more than 10 business days before change of occupant (N.J.A.C. 5:70-2.9(d), NJ Register October 2, 2017)","amount":"$45.00"},{"label":"State rule: request received 4 to 10 business days before change of occupant (2017)","amount":"$90.00"},{"label":"State rule: request received fewer than 4 business days before change of occupant (2017)","amount":"$161.00"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://www.penningtonboro.org/1239/Borough-Home-Sale-Checklist","label":"Official source (penningtonboro.org)"},{"url":"https://www.penningtonboro.org/DocumentCenter/View/1710/Ordinance-2026---3---Changing-Enforcement-Agencies-Under-Fire-Codedocx","label":"Official source (penningtonboro.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/adopted_amendment_5_10_2.9.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Inspection Services - Request services, schedule appointments, and pay fees 24/7 through the DCA website at$t$, $t$94efa7c92b42caeb2086194f880163b2440519d0a0155723445e21ae9952b3b5$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1108.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1108.json$t$, true),
  ($t$1111$t$, $t$Trenton$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Housing Code Compliance$t$, $j$["Issued by: City of Trenton Department of Inspections, Division of Housing Inspections","Contact: Yolanda Vazquez, Chief Housing Inspector · 609-989-3542 · yvazquez@trentonnj.org","How to apply: Apply to the Division of Housing Inspections, Department of Inspections, City Hall Annex, 319 East State Street, 2nd Floor, Trenton, NJ 08608 (609-989-3550; Housing Inspections line 609-989-3563). No online application form was found; call the Division for the application. If the certificate cannot be obtained before closing, the owner may file an affidavit that the home will not be occupied until the certificate is issued. A Certificate of Approval or Certificate of Continued Occupancy is accepted instead.","Home must conform to the City's existing Zoning and Fire Safety Codes","Smoke detector and carbon monoxide alarm compliance (City Code Chapter 132, Section 40)","Must substantially meet the City's minimum habitability standards (Chapter 132, Articles V-VIII)","Electrical and plumbing service and fixtures must be safe, sound and sturdy and not create a fire, safety or life hazard","Also: Zoning conformity: The Certificate of Housing Code Compliance certifies the home conforms to the City's existing Zoning Code.","Also: Affidavit option: If the certificate is not ready, the sale may close if the owner files an affidavit that the property will not be occupied until the certificate is obtained."]$j$::jsonb, $j$[{"label":"Certificate of Housing Code Compliance (1 to 4 units)","amount":"$200"},{"label":"Each unit over four (structures with more than four units)","amount":"$15 per unit"},{"label":"Each re-inspection after the first (1 and 2 unit homes)","amount":"$50"}]$j$::jsonb, null, $t$https://trentonnj.org/233/Housing-Inspections$t$, $j$[{"url":"https://trentonnj.org/233/Housing-Inspections","label":"Official source (trentonnj.org)"},{"url":"https://trentonnj.org/231/Inspections-Department","label":"Official source (trentonnj.org)"}]$j$::jsonb, $t$Prior to the change of ownership of any residential property a Certificate of Housing Code Compliance shall have first been obtained from the Department of Inspections, Division of Housing Inspections.$t$, $t$054591c386d99000ccbb3b1214d173612d581ad41a5f8194d531d4eb0099c3e9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1111.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1111.json$t$, true),
  ($t$1111$t$, $t$Trenton$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Trenton Division of Housing Inspections (smoke/CO compliance is part of the Certificate of Housing Code Compliance); NJ DCA Division of Fire Safety is the fire code enforcing agency but is… (town fire bureau)","Contact: Yolanda Vazquez, Chief Housing Inspector · 609-989-3542 · yvazquez@trentonnj.org","How to apply: Handled through the Division of Housing Inspections resale certificate (319 East State Street, 2nd Floor Annex; 609-989-3550). Confirm by phone whether a separate smoke/CO certificate is issued.","Fire official in the NJ state directory (NJ DCA, state), updated 6/3/2026: Louis Kilmer · (609) 633-6132","Smoke detector and carbon monoxide compliance is certified as part of the City's Certificate of Housing Code Compliance (City Code Chapter 132, Section 40)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Included in the Certificate of Housing Code Compliance fee (no separate smoke/CO fee published)","amount":"$200"}]$j$::jsonb, null, $t$https://trentonnj.org/233/Housing-Inspections$t$, $j$[{"url":"https://trentonnj.org/233/Housing-Inspections","label":"Official source (trentonnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://trentonnj.org/231/Inspections-Department","label":"Official source (trentonnj.org)"}]$j$::jsonb, $t$This document issued by the Director shall certify that the residential property conforms to the existing Zoning and Fire Safety Codes of the City of Trenton, Smoke Detector and Carbon Monoxide Compliance as set forth in Chapter 132 Section 40$t$, $t$9a79d7a02d9db9aea035936461e730a97299d756c0e963c2e91e2deb24c0f4a3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1111.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1111.json$t$, true),
  ($t$1112$t$, $t$Robbinsville Township$t$, $t$MERCER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Inspection (formerly Certificate of Continued Occupancy, CCO)$t$, $j$["Issued by: Robbinsville Township Construction Office (Construction & Housing / Code Enforcement)","Contact: Sandy DeLorenzo, Administrative Assistant (CCO Inspections/Information), Construction Office · 609-259-3600 Ext. 1113 · sdelorenzo@robbinsville.net","How to apply: Complete the Residential Certificate of Inspection request form and mail or drop it off at the Construction Office, 2300 Route 33, Robbinsville, NJ 08691, with a check or money order payable to Township of Robbinsville, credit card or exact cash. Inspections are scheduled Monday through Thursday between 3:30 pm and 6:00 pm only. Office hours 7:30 am to 3:30 pm.","Valid for: 60 days after issue","Smoke detectors on every level including the basement (not crawl spaces or unfinished attics); battery units must be 10-year sealed battery","Carbon monoxide detector no more than 10 feet outside the bedroom door (battery or electric)","No cracked window glass or broken window seals (cloudy panes)","Anti-tip bracket installed for the stove","No leaking pipes or faucets","No exposed wiring (uncovered junction boxes, switches, outlets, wire nuts)","Handrails on all stairways of four or more steps","No peeling paint","Furnace flue sealed at the chimney","Pools need an enclosure with self-closing, self-latching gates that swing away from the pool","No garbage disposal under the kitchen sink when the home is on public sewer","Private well: Private Well Testing Act water test results","Septic: report on the State Onsite System Inspection Form by a licensed septic inspector","If the home will be rented, the owner must first register as a landlord with the Clerk's Office","Also: Open permits and landlord registration: The request form's office section checks 'Registered as landlord?' and 'Open permits?'. If the home will be rented, the owner must register as a landlord with the Clerk's Office before an inspection is scheduled.","Also: Private well and septic: Homes with a private well must provide Private Well Testing Act results; homes with septic must provide a septic report on the State Onsite System Inspection Form by a licensed septic inspector."]$j$::jsonb, $j$[{"label":"Single family / townhouse","amount":"$100"},{"label":"Condo / mobile home / rental","amount":"$75"},{"label":"Each reinspection","amount":"$50"}]$j$::jsonb, $t$https://www.robbinsville.net/7-30-26-%20CCI%20Residential%20ALL%20INSTRUCTIONS.pdf$t$, $t$https://www.robbinsville-twp.org/departments/construction_building_permits/certificates_of_inspection/index.php$t$, $j$[{"url":"https://www.robbinsville-twp.org/departments/construction_building_permits/certificates_of_inspection/index.php","label":"Official source (robbinsville-twp.org)"},{"url":"https://www.robbinsville.net/7-30-26-%20CCI%20Residential%20ALL%20INSTRUCTIONS.pdf","label":"Official source (robbinsville.net)"},{"url":"https://www.robbinsville-twp.org/departments/construction_building_permits/contact_us.php","label":"Official source (robbinsville-twp.org)"}]$j$::jsonb, $t$RESIDENTIAL & COMMERCIAL CERTIFICATES OF INSPECTION Formerly referred to as "Certificates of Continued Occupancy"$t$, $t$c30c59cdae53cd0db18b5a230ab6191a6757e93efa473b2e66724c9d57fa0395$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1112.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1112.json$t$, true),
  ($t$1112$t$, $t$Robbinsville Township$t$, $t$MERCER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Robbinsville Township Construction Office (smoke and CO checked in the Certificate of Inspection; the state directory lists the Construction Office for smoke detector compliance). The Robbinsville… (town fire bureau)","Contact: Sandy DeLorenzo, Administrative Assistant (CCO Inspections/Information), Construction Office · 609-259-3600 Ext. 1113 · sdelorenzo@robbinsville.net","How to apply: Through the Construction Office residential Certificate of Inspection request (609-259-3600 Ext. 1113). No separate smoke/CO certificate form or fee was found on the Township site; the Fire Department website is behind a bot check.","Fire official in the NJ state directory, updated 1/14/2026: Brian F Johnson · (609) 259-7814 · bjohnson@robbinsville.net","Smoke/CO alarms are checked as 'State Mandated Requirements' in the Township CCO (Certificate of Inspection) inspection","Battery smoke detectors must be 10-year sealed battery type","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.robbinsville.net/7-30-26-%20CCI%20Residential%20ALL%20INSTRUCTIONS.pdf$t$, $t$https://www.robbinsville-twp.org/departments/construction_building_permits/certificates_of_inspection/index.php$t$, $j$[{"url":"https://www.robbinsville.net/7-30-26-%20CCI%20Residential%20ALL%20INSTRUCTIONS.pdf","label":"Official source (robbinsville.net)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.robbinsville-twp.org/departments/construction_building_permits/contact_us.php","label":"Official source (robbinsville-twp.org)"}]$j$::jsonb, $t$Smoke Detectors are required on every level of a home including the basement, excluding crawl spaces and unfinished attics. Battery operated smoke detectors SHALL HAVE 10 YEAR SEALED BATTERY.$t$, $t$1f291a12a19d26d83bac5b3855e89dca078e7ae1a5d77ac53dbeb9cefccc9bf3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1112.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1112.json$t$, true)
